n=16
coords=[(0,7),(1,8),(2,5),(2,9),(3,6),(3,10),(4,7),(4,11),(5,8),(5,12),(6,4),(6,9),(6,13),(7,5),(7,10),(7,14),(8,6),(8,11),(8,15),(9,7),(9,12),(10,8),(10,13),(11,4),(11,9),(12,5)]
wall=set(coords)
from collections import deque
for conn in [4,8]:
    seen=set(); q=deque()
    for r in range(n):
        for c in range(n):
            if (r in (0,n-1) or c in (0,n-1)) and (r,c) not in wall:
                seen.add((r,c)); q.append((r,c))
    ds=[(-1,0),(1,0),(0,-1),(0,1)]
    if conn==8: ds+= [(-1,-1),(-1,1),(1,-1),(1,1)]
    while q:
        r,c=q.popleft()
        for dr,dc in ds:
            x,y=r+dr,c+dc
            if 0<=x<n and 0<=y<n and (x,y) not in wall and (x,y) not in seen:
                seen.add((x,y)); q.append((x,y))
    inside={(r,c) for r in range(n) for c in range(n) if (r,c) not in wall and (r,c) not in seen}
    print(conn, len(inside), sorted(inside)[:20])

